import numpy as np
import pytest

from ar import (
    ols_ar2,
    poly_roots,
    simulate_ar2,
    theoretical_variance,
    yule_walker,
)

A1_TRUE, A2_TRUE = 0.6, -0.28


@pytest.fixture(scope="module")
def data():
    return simulate_ar2(A1_TRUE, A2_TRUE, n=20000, burn_in=500, seed=3)


@pytest.fixture(scope="module")
def fits(data):
    phi_yw, sig_yw = yule_walker(data)
    phi_ols, resid = ols_ar2(data)
    return phi_yw, sig_yw, phi_ols, resid


def test_yule_walker_recovers_coefficients(fits):
    phi_yw, _, _, _ = fits
    assert abs(phi_yw[0] - A1_TRUE) < 0.02
    assert abs(phi_yw[1] - A2_TRUE) < 0.02


def test_ols_recovers_coefficients(fits):
    _, _, phi_ols, _ = fits
    assert abs(phi_ols[0] - A1_TRUE) < 0.02
    assert abs(phi_ols[1] - A2_TRUE) < 0.02


def test_estimators_agree(fits):
    phi_yw, _, phi_ols, _ = fits
    assert abs(phi_yw[0] - phi_ols[0]) < 0.01
    assert abs(phi_yw[1] - phi_ols[1]) < 0.01


def test_one_step_rmse_near_innovation_sigma(fits):
    _, _, _, resid = fits
    rmse = np.sqrt(np.mean(resid[-2000:] ** 2))
    assert abs(rmse - 1.0) / 1.0 < 0.03


def test_sample_vs_theoretical_variance(data):
    var_theory = theoretical_variance(A1_TRUE, A2_TRUE)
    var_sample = float(np.var(data))
    assert abs(var_sample - var_theory) / var_theory < 0.05


def test_stationarity_roots_outside_unit_circle(fits):
    _, _, phi_ols, _ = fits
    roots = poly_roots(*phi_ols)
    assert np.min(np.abs(roots)) > 1.01

